mapper.select:
SELECT MAX(issued_at)
FROM email_verification
WHERE company_id = #{companyId} AND purpose_code = #{purpose}

SELECT sent_count
FROM email_rate_limit
WHERE company_id = #{companyId} AND email = #{email} AND purpose_code = #{purpose} AND quota_date = #{today}

mapper.update:
UPDATE email_verification
SET revoked_at = #{now}, updated_at = #{now}
WHERE company_id = #{companyId} AND purpose_code = #{purpose}
  AND consumed_at IS NULL AND revoked_at IS NULL

UPDATE email_verification
SET verified_at = #{now}, consumed_at = #{now}, updated_at = #{now}
WHERE email_verification_id = #{id} AND company_id = #{companyId}
  AND consumed_at IS NULL AND revoked_at IS NULL AND expires_at > #{now}
